mapper.select:
SELECT *
FROM chat_conversation
WHERE conversation_type = #{conversationType}
  AND task_id = #{taskId}
LIMIT 1

SELECT , ( SELECT COUNT(*) FROM chat_message AS unread_message WHERE unread_message.conversation_id = c.id AND unread_message.deleted = 0 AND unread_message.id > COALESCE(self_member.last_read_message_id, 0) AND ( unread_message.sender_id IS NULL OR unread_message.sender_id <> #{userId} ) ) AS unread_count FROM chat_conversation AS c INNER JOIN chat_conversation_member AS self_member ON self_member.conversation_id = c.id AND self_member.user_id = #{userId} AND self_member.left_at IS NULL LEFT JOIN meter_reading_task AS task ON task.id = c.task_id LEFT JOIN chat_message AS last_message ON last_message.id = c.last_message_id WHERE 1 = 1
AND c.conversation_type = #{conversationType}
AND c.status = #{status}
ORDER BY COALESCE(c.last_message_at, c.created_at) DESC, c.id DESC

SELECT , CAST(0 AS SIGNED) AS unread_count FROM chat_conversation AS c LEFT JOIN meter_reading_task AS task ON task.id = c.task_id LEFT JOIN chat_message AS last_message ON last_message.id = c.last_message_id WHERE 1 = 1
AND c.conversation_type = #{conversationType}
AND c.status = #{status}
ORDER BY COALESCE(c.last_message_at, c.created_at) DESC, c.id DESC
